export type PaymentPlan = "Full" | "Monthly" | "Seasonal";
export type PaymentStatus = "Paid" | "Partial" | "Overdue" | "Pending";
export type PaymentMethod = "Card" | "Cash" | "Bank Transfer";

export interface PaymentInvoice {
  id: string;
  amount: number;
  date: string;
  method: PaymentMethod;
  receiptUrl: string;
}

export interface MockPayment {
  id: string;
  participantId: string;
  participantName: string;
  location: string;
  session: string;
  plan: PaymentPlan;
  totalFee: number;
  paidAmount: number;
  balance: number;
  status: PaymentStatus;
  lastPaymentDate: string;
  nextDueDate: string;
  invoices: PaymentInvoice[];
}

const make = (
  id: string,
  participantId: string,
  participantName: string,
  location: string,
  session: string,
  plan: PaymentPlan,
  totalFee: number,
  paidAmount: number,
  status: PaymentStatus,
  lastPaymentDate: string,
  nextDueDate: string,
  invoices: PaymentInvoice[],
): MockPayment => ({
  id, participantId, participantName, location, session, plan,
  totalFee, paidAmount, balance: totalFee - paidAmount,
  status, lastPaymentDate, nextDueDate, invoices,
});

